    private sealed class ScriptedClient(params int[] statuses) : IApiClient
    {
        public List<Dictionary<string, string>> Sent { get; } = [];

        public Task<ApiHttpResponse> SendRequestAsync(
            string method,
            Uri url,
            Dictionary<string, string> headers,
