            object? body,
            bool noRedirect,
            Func<Task<Dictionary<string, string>>>? refreshHeaders,
            int? timeout,
            int? maxRetries,
            CancellationToken cancellationToken
        )
        {
            Dictionary<string, string> current = headers;
            while (true)
            {
                int index = Sent.Count;
                Sent.Add(new Dictionary<string, string>(current));
                int status = statuses[Math.Min(index, statuses.Length - 1)];
                if (status == 503 && refreshHeaders is not null && index + 1 < statuses.Length)
                {
                    current = await refreshHeaders();
                    continue;
                }
                return new ApiHttpResponse(status, "{}", new Dictionary<string, string>());
            }
        }
    }

