        Assert.NotNull(outer);

        ScriptedClient client = await CallThroughTheSdkAsync(hook);

        Activity span = Assert.Single(_stopped);
        Assert.Equal(outer.Id, span.ParentId);
        Assert.Same(outer, Activity.Current);
        string[] traceparents = client
            .Sent.Single()
            .Where(h => h.Key.Equals("traceparent", StringComparison.OrdinalIgnoreCase))
            .Select(h => h.Value)
            .ToArray();
        string traceparent = Assert.Single(traceparents);
        Assert.Equal(span.Id, traceparent);
    }

